/**
 * Names checked against the web and the shops, 19 Oct 2026 (docs/NAME-VERIFICATION-2026-10-19.md).
 *
 * Scope: the families that sit on products listed by 3 or more shops, whose name has the house in it,
 * a noise word or a trailing connector. Append only: an entry is never changed or removed, and a
 * family in any list is never reopened. The one move allowed: a family in NAME_UNRESOLVED that the
 * owner settles leaves it for the list of the decision (a family is in one list), with `decision` set.
 *
 * NAME_VERIFIED renames a displayed name, applied at the end of displayName. A rename may only
 * DELETE words (the new name is a word subsequence of the old one), keeps line and series prefixes
 * and audience labels, and has two sources on different domains (a brand page, a major retailer or a
 * fragrance database). NAME_KEPT names are the real name (the house is part of it, or it is the
 * house plus an audience label). NAME_UNRESOLVED needs the owner; nothing changes for them.
 */
export interface ReviewedName {
  brand: string;
  from: string;
  to: string;
  on: string;
  sources: readonly string[];
  evidence: string;
}
export interface KeptName {
  brand: string;
  name: string;
  on: string;
  sources: readonly string[];
  evidence: string;
  /** Set when the owner settled the family: such an entry needs no source. */
  decision?: string;
}
export interface UnresolvedName { brand: string; name: string; proposed: string; on: string; sources: readonly string[]; why: string }

